{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 bucket does not have cross-region replication enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured for cross-region replication, which could lead to data loss in case of a region-specific disaster."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not have object lock enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have object lock enabled, which could lead to accidental or malicious deletion of data."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have versioning enabled, making it difficult to recover from accidental deletion or overwrite of data."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
    }, {
  })
  versioning {
    enabled = true
  }
  replication_configuration {
    role = aws_iam_role.replication.arn
  }
  object_lock_configuration {
    object_lock_enabled = "Enabled"
  }
}
resource "aws_iam_role" "replication" {
  name        = "${local.resource_prefix.value}-replication"
  description = "S3 replication role for ${local.resource_prefix.value}-data"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}",
  "fix_summary": "Enabled versioning on the S3 bucket, added a basic replication configuration with a new IAM role, and enabled object lock configuration to improve data durability and protection."
}
